/*
 * main-dlg-ui.c — GTK4/libadwaita port.
 *
 * The original file was generated by Glade and constructed the dialog
 * widget by widget. The layout now lives in data/luxeappearance.ui and is
 * loaded with GtkBuilder. The create_dlg() signature is unchanged so all
 * call sites keep working; lookup_widget() resolves names through the
 * registered builder (see glade-support.c). The GtkApplicationWindow,
 * header bar, and hamburger menu (About action) all live in the .ui file.
 */

#ifdef HAVE_CONFIG_H
#  include <config.h>
#endif

#include <gtk/gtk.h>

#include "main-dlg.h"
#include "main-dlg-ui.h"
#include "glade-support.h"

GtkWidget*
create_dlg (void)
{
    GtkBuilder* builder = glade_load_ui("luxeappearance.ui");
    GtkWidget* dlg;

    if(!builder)
        return NULL;

    dlg = GTK_WIDGET(gtk_builder_get_object(builder, "dlg"));
    if(!dlg)
    {
        g_warning("luxeappearance: 'dlg' not found in luxeappearance.ui");
        /* The builder is owned by the registry; drop only this failed
         * builder so a previously loaded dialog remains valid. */
        glade_unregister_builder(builder);
        return NULL;
    }

    return dlg;
}
